import { promises as fs } from "node:fs";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { wikiAbsPath } from "@/lib/wiki/paths";

// 추출본(정규화 markdown 사이드카) 열람 — AI가 읽은 텍스트를 사용자도 확인. docs/17 §6.
export const runtime = "nodejs";

export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return new Response("로그인이 필요합니다.", { status: 401 });
  const id = Number((await params).id);
  if (!Number.isInteger(id) || id <= 0) return new Response("잘못된 id입니다.", { status: 400 });

  const source = await prisma.source.findUnique({ where: { id } });
  if (!source || !source.normalizedPath) {
    return new Response("추출본이 없습니다.", { status: 404 });
  }
  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
  if (!allowed.has(source.teamScope)) return new Response("접근 권한이 없습니다.", { status: 403 });

  try {
    const md = await fs.readFile(wikiAbsPath(source.normalizedPath), "utf8");
    return new Response(md, { headers: { "content-type": "text/markdown; charset=utf-8" } });
  } catch {
    return new Response("추출본 파일을 찾을 수 없습니다.", { status: 404 });
  }
}

