import {
  IconFile, IconPhoto, IconMarkdown, IconFileTypePdf, IconFileTypeDocx, IconFileTypeXls,
  IconFileTypePpt, IconFileTypeCsv, IconFileTypeHtml, IconLanguageHiragana, IconFileText,
  IconUsers, IconBulb, IconTopologyStar3, IconMessage2, IconBook2, IconFolder,
  type Icon as TablerIcon,
} from "@tabler/icons-react";

// 자료 타입(Source.type=PDF/IMAGE/DOCX/…) → 파일 아이콘. 자료 탭·위키 탭 공용.
const TYPE_ICON: Record<string, TablerIcon> = {
  PDF: IconFileTypePdf, IMAGE: IconPhoto,
  DOCX: IconFileTypeDocx, DOC: IconFileTypeDocx,
  XLSX: IconFileTypeXls, XLS: IconFileTypeXls, ODS: IconFileTypeXls,
  CSV: IconFileTypeCsv, PPTX: IconFileTypePpt, ODP: IconFileTypePpt,
  HTML: IconFileTypeHtml, MD: IconMarkdown, MARKDOWN: IconMarkdown,
  HWP: IconLanguageHiragana, HWPX: IconLanguageHiragana,
  TXT: IconFileText, RTF: IconFileText, ODT: IconFileText, JSON: IconFileText,
};
export const typeIcon = (t: string): TablerIcon => TYPE_ICON[(t || "").toUpperCase()] || IconFile;

// 자료 타입 → 화면 표시용 한국어 라벨. 영어 단어로 읽히는 것(IMAGE·TEXT…)·브랜드명은 한글로,
// 표준 포맷 약어(PDF·CSV·HTML·JSON)는 그대로 둔다. 없으면 대문자 약어 그대로.
const TYPE_LABEL: Record<string, string> = {
  IMAGE: "이미지",
  TXT: "텍스트", TEXT: "텍스트", ODT: "텍스트 문서", RTF: "서식 텍스트",
  MD: "마크다운", MARKDOWN: "마크다운",
  HWP: "한글", HWPX: "한글",
  DOC: "워드", DOCX: "워드",
  XLS: "엑셀", XLSX: "엑셀", ODS: "엑셀",
  PPT: "파워포인트", PPTX: "파워포인트", ODP: "파워포인트",
};
export const typeLabel = (t: string): string => TYPE_LABEL[(t || "").toUpperCase()] || (t || "").toUpperCase();

// 위키 카테고리 폴더명(영문 slug) → 화면 표시용 한국어 라벨. 경로(path)는 영문 그대로, 표시만 한국어.
const CATEGORY_LABEL: Record<string, string> = {
  entities: "개체", concepts: "개념", topics: "주제", queries: "질의",
};
export const categoryLabel = (name: string): string => CATEGORY_LABEL[name.toLowerCase()] ?? name;

// 위키 페이지 경로의 카테고리(디렉터리)로 트리 아이콘 구분.
export function categoryIcon(relName: string, isFile: boolean): TablerIcon {
  const n = relName.toLowerCase();
  if (!isFile) {
    if (n === "entities") return IconUsers;
    if (n === "concepts") return IconBulb;
    if (n === "topics") return IconTopologyStar3;
    if (n === "queries") return IconMessage2;
    return IconFolder;
  }
  if (n === "index.md") return IconBook2;
  return IconFileText;
}

