export const typeLabel = (t: string): string => TYPE_LABEL[(t || "").toUpperCase()] || (t || "").toUpperCase();

// 자료를 ★브라우저에서 볼 수 있는★ URL. PDF·이미지는 브라우저가 원본을 직접 렌더하므로 원본(/raw)을,
// 그 외(엑셀·워드·PPT 등 브라우저가 못 여는 포맷)는 ★추출본 markdown★(/extracted)으로 — 추출본이 없으면 원본 폴백.
// 자료 탭의 분리된 '원본 열기'(/raw)·'추출본'(/extracted) 규약과 동일 철학으로, 위키 출처 링크가 항상 '보이게' 한다.
export function materialViewUrl(id: number, type?: string, hasExtracted?: boolean): string {
  const t = (type || "").toUpperCase();
  const nativelyViewable = t === "PDF" || t === "IMAGE";
  return !nativelyViewable && hasExtracted
    ? `/api/materials/${id}/extracted`
    : `/api/materials/${id}/raw`;
}

