import { promises as fs } from "node:fs";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { wikiAbsPath } from "@/lib/wiki/paths";

// 원본 자료 열람 — 업로드한 PDF·이미지·md 원본 그대로 반환(미리보기/다운로드). ACL 검사.
export const runtime = "nodejs";

const CTYPE: Record<string, string> = {
  pdf: "application/pdf",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  md: "text/markdown; charset=utf-8",
  txt: "text/plain; charset=utf-8",
};

export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return new Response("로그인이 필요합니다.", { status: 401 });
  const id = Number((await params).id);
  if (!Number.isInteger(id) || id <= 0) return new Response("잘못된 id입니다.", { status: 400 });

  const source = await prisma.source.findUnique({ where: { id } });
  if (!source) return new Response("자료를 찾을 수 없습니다.", { status: 404 });

  // ACL: 접근 가능한 scope의 자료만
  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
  if (!allowed.has(source.teamScope)) return new Response("접근 권한이 없습니다.", { status: 403 });

  let bytes: Buffer;
  try {
    bytes = await fs.readFile(wikiAbsPath(source.rawPath));
  } catch {
    return new Response("원본 파일을 찾을 수 없습니다.", { status: 404 });
  }

  const ext = (source.rawPath.split(".").pop() || "").toLowerCase();
  const ctype = CTYPE[ext] || "application/octet-stream";
  const filename = encodeURIComponent(`${source.title}.${ext}`);
  return new Response(new Uint8Array(bytes), {
    headers: {
      "content-type": ctype,
      "content-disposition": `inline; filename*=UTF-8''${filename}`,
      "cache-control": "private, max-age=60",
    },
  });
}

