import { NextResponse } from "next/server";
import { promises as fs } from "node:fs";
import path from "node:path";
import { getSessionUser } from "@/lib/auth/session";
import { allowedScopes, scopeWikiPrefix } from "@/lib/acl/scope";
import { prisma } from "@/lib/db";
import { wikiAbsPath } from "@/lib/wiki/paths";

// 자료(원본)로부터 생성된 위키 페이지 경로 — sha를 인용한 scope 내 .md 페이지. 자료↔위키 이동용.
export const runtime = "nodejs";

export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const id = Number((await params).id);
  if (!Number.isInteger(id) || id <= 0) return NextResponse.json({ error: "잘못된 id입니다." }, { status: 400 });

  const source = await prisma.source.findUnique({ where: { id } });
  if (!source) return NextResponse.json({ error: "자료를 찾을 수 없습니다." }, { status: 404 });
  const { sha256: sha, teamScope } = source;
  const allowed = new Set((await allowedScopes(user)).map((s) => scopeWikiPrefix(s.id)));
  if (!allowed.has(teamScope)) return NextResponse.json({ error: "접근 권한이 없습니다." }, { status: 403 });

  const paths: string[] = [];
  async function walk(absDir: string, relBase: string) {
    let entries: import("node:fs").Dirent[];
    try { entries = await fs.readdir(absDir, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      if (e.name.startsWith(".")) continue;
      const abs = path.join(absDir, e.name);
      const rel = `${relBase}/${e.name}`;
      if (e.isDirectory()) await walk(abs, rel);
      else if (e.name.endsWith(".md") && e.name !== "index.md" && e.name !== "log.md") {
        const c = await fs.readFile(abs, "utf8");
        if (c.includes(sha)) paths.push(rel);
      }
    }
  }
  await walk(wikiAbsPath(teamScope), teamScope);
  return NextResponse.json({ paths });
}

