"use client";

import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties } from "react";
import { createPortal } from "react-dom";
import { IconChevronDown, IconCheck } from "@tabler/icons-react";

// 네이티브 <select>는 펼친 목록의 모서리·너비·옵션 스타일을 OS가 그려 제어가 안 된다.
// → 커스텀 드롭다운. 팝업은 ★portal로 body에 띄워★ 부모 overflow/stacking에 가려지지 않게 하고
//    버튼 위치(getBoundingClientRect) 기준으로 fixed 배치한다.

export interface ModelOpt {
  id: string; label: string; provider: string; enabled: boolean;
  note?: string; kind?: "primary" | "backup"; backupOf?: string;
}

const DOT: Record<string, string> = {
  gemini: "#f59e0b", "openai-compat": "#3b82f6", ollama: "#22c55e", anthropic: "#a855f7", codex: "#10a37f", "claude-cli": "#d97757", openai: "#0ea5e9",
};
// 사용량만큼 ★종량 과금★되는 공급자(API 결제). 구독(codex/claude-cli)·무료(gemini/groq)·로컬(ollama)과 구분해 경고.
const PAID = (p?: string) => p === "openai" || p === "anthropic";
// ★무료 모델(Gemini=주황 등)과 색이 겹치지 않게★ 채워진 로즈(과금) 뱃지로 또렷이 구분.
const paidBadge = { fontSize: 9.5, fontWeight: 700, color: "#fff", background: "#e11d48", borderRadius: 4, padding: "0 4px", marginLeft: 5, flexShrink: 0 } as const;

function optState(m: ModelOpt, all: ModelOpt[]): { selectable: boolean; reason: string } {
  if (!m.enabled) return { selectable: false, reason: m.note || "사용 불가" };
  if (m.kind === "backup" && all.some((p) => p.id === m.backupOf && p.enabled)) {
    return { selectable: false, reason: "자동전환 전용" };
  }
  return { selectable: true, reason: "" };
}

export default function ModelSelect({
  models, value, onChange, disabled, title, variant = "chat",
}: {
  models: ModelOpt[];
  value: string;
  onChange: (id: string) => void;
  disabled?: boolean;
  title?: string;
  variant?: "chat" | "mat";
}) {
  const [open, setOpen] = useState(false);
  const [pos, setPos] = useState<CSSProperties | null>(null);
  const wrapRef = useRef<HTMLDivElement>(null);
  const popRef = useRef<HTMLDivElement>(null);
  const btnRef = useRef<HTMLButtonElement>(null);

  const place = () => {
    const r = btnRef.current?.getBoundingClientRect();
    if (!r) return;
    const gap = 5;
    // 너비: 버튼 너비 이상으로 시작하되 내용(긴 라벨)에 맞춰 넓어지고, 화면 오른쪽은 안 넘게 제한.
    const minWidth = r.width;
    const maxWidth = Math.max(r.width, Math.min(460, window.innerWidth - r.left - 8));
    if (variant === "chat") {
      // 하단 툴바 → 위로 펼침
      setPos({ position: "fixed", left: r.left, minWidth, maxWidth, bottom: window.innerHeight - r.top + gap, maxHeight: Math.min(340, r.top - 12) });
    } else {
      // 상단 폼 → 아래로 펼침
      setPos({ position: "fixed", left: r.left, minWidth, maxWidth, top: r.bottom + gap, maxHeight: Math.min(340, window.innerHeight - r.bottom - 12) });
    }
  };

  useLayoutEffect(() => { if (open) place(); /* eslint-disable-next-line */ }, [open]);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      const t = e.target as Node;
      if (wrapRef.current?.contains(t) || popRef.current?.contains(t)) return;
      setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    const reposition = () => place();
    document.addEventListener("mousedown", onDoc);
    document.addEventListener("keydown", onKey);
    window.addEventListener("resize", reposition);
    window.addEventListener("scroll", reposition, true); // 내부 스크롤까지 추적
    return () => {
      document.removeEventListener("mousedown", onDoc);
      document.removeEventListener("keydown", onKey);
      window.removeEventListener("resize", reposition);
      window.removeEventListener("scroll", reposition, true);
    };
    // eslint-disable-next-line
  }, [open]);

  const selected = models.find((m) => m.id === value);
  const selLabel = selected ? selected.label.replace(/^↳ 백업 · /, "") : "모델 선택";

  return (
    <div className={`msel msel-${variant}${open ? " open" : ""}`} ref={wrapRef}>
      <button ref={btnRef} type="button" className="msel-btn" disabled={disabled} title={title}
        aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        {selected && <span className="msel-dot" style={{ background: DOT[selected.provider] || "var(--color-text-tertiary)" }} />}
        <span className="msel-btn-label">{selLabel}</span>
        {selected && PAID(selected.provider) && <span style={paidBadge} title="사용량만큼 과금(종량제)">과금</span>}
        <IconChevronDown size={14} className={`msel-caret${open ? " up" : ""}`} />
      </button>
      {open && pos && typeof document !== "undefined" && createPortal(
        <div className="msel-pop" role="listbox" ref={popRef} style={pos}>
          {models.map((m) => {
            const st = optState(m, models);
            const isSel = m.id === value;
            const name = m.label.replace(/^↳ 백업 · /, "");
            return (
              <button key={m.id} type="button" role="option" aria-selected={isSel} disabled={!st.selectable}
